package org.eternalself.umbrielremote;
import android.app.*;
import android.graphics.*;
import android.os.*;
import android.util.Base64;
import android.view.*;
import android.widget.*;
import org.json.*;
/** A visible, bounded preview. No frames, images, or polling survive leaving the screen. */
final class ScreenPanel extends LinearLayout {
 final RemoteDashboard d;final UiDesign ui;final Handler handler=new Handler(Looper.getMainLooper());final TextView status;final ImageView image;final Button start,refresh,stop;final Switch live;boolean active,requested,busy,disposed;int epoch;Dialog fullscreen;ImageView fullscreenImage;
 ScreenPanel(RemoteDashboard dashboard){super(dashboard.activity);d=dashboard;ui=d.ui;setOrientation(VERTICAL);setPadding(ui.dp(20),ui.dp(20),ui.dp(20),ui.dp(20));setBackground(ui.shape(ui.surface,26));ui.add(this,ui.label(Messages.t("Pantalla de la PC"),20,ui.text,true),8);ui.add(this,ui.label(Messages.t("Solicita permiso en la computadora y elige allí qué pantalla compartir. La vista dura hasta 5 minutos."),14,ui.muted,false),12);status=ui.label(Messages.t("La pantalla no se está compartiendo"),13,ui.muted,false);ui.add(this,status,12);image=new ZoomImage(d.activity);image.setBackground(ui.shape(ui.raised,16));image.setMinimumHeight(ui.dp(180));image.setContentDescription(Messages.t("Vista de la pantalla de la computadora"));addView(image,new LinearLayout.LayoutParams(-1,ui.dp(220)));LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)image.getLayoutParams();lp.bottomMargin=ui.dp(12);
  start=ui.button(Messages.t("Solicitar pantalla"),true);start.setEnabled(d.features.optBoolean("screen"));ui.add(this,start,12);start.setOnClickListener(v->{if(disposed)return;active=true;d.activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);requested=true;d.owner.screenRequested=true;start.setEnabled(false);status.setText(Messages.t("Confirma en la ventana de Umbriel Connect de la PC…"));int version=epoch;d.request("screen-open",new JSONObject(),r->{if(!active||disposed||version!=epoch)return;if(!r.optBoolean("ok")){clear();start.setEnabled(true);status.setText(r.optString("error"));return;}poll();});});
  live=new Switch(d.activity);live.setText(Messages.t("Actualización en vivo · hasta 2 imágenes/s"));live.setTextColor(ui.text);live.setMinHeight(ui.dp(52));ui.add(this,live,12);live.setOnCheckedChangeListener((b,on)->{if(active&&requested&&!busy)poll();});refresh=ui.button(Messages.t("Actualizar imagen"),false);refresh.setEnabled(false);refresh.setOnClickListener(v->frame());ui.add(this,refresh,12);Button expand=ui.button(Messages.t("Ampliar imagen"),false);expand.setOnClickListener(v->{if(image.getDrawable()==null)return;fullscreen=new Dialog(d.activity,android.R.style.Theme_Material_NoActionBar_Fullscreen);ImageView large=new ZoomImage(d.activity);fullscreenImage=large;large.setBackgroundColor(Color.BLACK);large.setImageDrawable(image.getDrawable());fullscreen.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);fullscreen.setContentView(large);fullscreen.show();});ui.add(this,expand,12);stop=ui.button(Messages.t("Detener vista"),false);stop.setOnClickListener(v->pause());ui.add(this,stop,0);
 }
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();active=!disposed;d.activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);if(active&&d.owner.screenRequested){requested=true;start.setEnabled(false);poll();}}
 @Override protected void onDetachedFromWindow(){pause();super.onDetachedFromWindow();}
 void poll(){if(!active||!requested||busy)return;busy=true;int version=epoch;d.request("screen-status",new JSONObject(),r->{busy=false;if(!active||version!=epoch)return;JSONObject value=r.optJSONObject("value");String state=value==null?"closed":value.optString("state");if(!r.optBoolean("ok")||state.equals("closed")){clear();status.setText(Messages.t("La solicitud de pantalla terminó"));return;}if(state.equals("approved")){status.setText(Messages.t("Compartiendo · ")+value.optString("name"));refresh.setEnabled(true);frame();}else handler.postDelayed(()->poll(),750);});}
 void frame(){if(!active||!requested||busy)return;handler.removeCallbacksAndMessages(null);busy=true;int version=epoch;d.request("screen-frame",d.object("continuous",live.isChecked()),r->{busy=false;if(!active||version!=epoch)return;JSONObject value=r.optJSONObject("value");if(!r.optBoolean("ok")||value==null){clear();status.setText(r.optString("error",Messages.t("No se pudo mostrar la pantalla")));return;}try{String jpeg=value.optString("jpeg");if(!jpeg.isEmpty()){if(jpeg.length()>400000)throw new IllegalArgumentException();byte[] bytes=Base64.decode(jpeg,Base64.NO_WRAP);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth<1||bounds.outHeight<1||bounds.outWidth>1280||bounds.outHeight>1280)throw new IllegalArgumentException();Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null)throw new IllegalArgumentException();image.setImageBitmap(bitmap);if(fullscreen!=null&&fullscreen.isShowing()&&fullscreenImage!=null)fullscreenImage.setImageBitmap(bitmap);}}catch(Exception error){clear();status.setText(Messages.t("La imagen de pantalla no es válida"));return;}if(live.isChecked())handler.postDelayed(()->frame(),500);});}
 void clear(){if(!d.activity.isChangingConfigurations())d.owner.screenRequested=false;requested=false;image.setImageDrawable(null);refresh.setEnabled(false);start.setEnabled(d.features.optBoolean("screen"));if(fullscreen!=null){fullscreen.dismiss();fullscreen=null;fullscreenImage=null;}handler.removeCallbacksAndMessages(null);epoch++;}
 void pause(){active=false;d.activity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);if(requested&&!d.activity.isChangingConfigurations())d.request("screen-close",new JSONObject(),r->{});clear();}
 void dispose(){pause();disposed=true;}
}
